insert into public.question_bank(category,difficulty,prompt,answer,explanation) values
('Nature','EASY','Which animal produces cube-shaped droppings?','The wombat','Wombats have a distinctive segmented intestine that forms compact, cube-like pellets.'),
('Nature','EASY','How many hearts does an octopus have?','Three','Two hearts pump blood to the gills; a third circulates it to the body.'),
('Science','EASY','Which planet has a day longer than its year?','Venus','Venus rotates once in about 243 Earth days and orbits the Sun in about 225.'),
('Food','EASY','Botanically, which common yellow fruit is a berry?','Banana','A banana develops from one flower ovary and has seeds, meeting the botanical berry definition.'),
('Nature','EASY','What is the collective noun for a group of flamingos?','A flamboyance','A group of flamingos is commonly called a flamboyance.'),
('History','MEDIUM','Which university was teaching before the Aztec Empire was founded?','The University of Oxford','Teaching at Oxford is recorded by 1096; the Aztec Empire formed in the 15th century.'),
('History','MEDIUM','Was Cleopatra closer in time to the Moon landing or the building of the Great Pyramid?','The Moon landing','Cleopatra lived roughly 2,000 years after the Great Pyramid and about 2,000 years before Apollo 11.'),
('Nature','EASY','Which animal has fingerprints remarkably similar to humans''?','The koala','Koala fingerprints have loops and ridges that can resemble human prints.'),
('Nature','EASY','Which insect tastes using sensors on its feet?','The butterfly','Butterflies have chemoreceptors on their feet that help them identify plants.'),
('Food','EASY','Which fruit is made of many berries fused together?','Pineapple','A pineapple forms from many flowers whose individual fruits merge around one central stem.'),
('Nature','MEDIUM','Which mammal has been observed using tools to crack shellfish?','The sea otter','Sea otters use rocks as anvils or hammers while opening hard-shelled prey.'),
('Nature','EASY','What is the only mammal capable of true sustained flight?','The bat','Bats generate powered flight; flying squirrels glide rather than fly.'),
('Nature','MEDIUM','Which animal can regrow a lost arm and sometimes an entire body from it?','The sea star','Some sea star species can regenerate extensively from a severed arm that retains part of the central disc.'),
('Nature','EASY','What color is a polar bear''s skin beneath its fur?','Black','Polar bear skin is dark; the hairs are translucent and scatter light.'),
('Nature','MEDIUM','Which bird can fly backward for sustained periods?','The hummingbird','Its wing joints allow a figure-eight stroke that produces lift on both halves of the beat.'),
('Nature','EASY','Which animal''s teeth continue growing throughout its life?','The beaver','Beaver incisors grow continuously and are worn down by gnawing.'),
('Nature','MEDIUM','What is the largest living species of lizard?','The Komodo dragon','Komodo dragons can exceed three metres in length.'),
('Nature','EASY','Which animal is known for sleeping while standing and locking its legs?','The horse','A stay apparatus lets horses rest while standing with little muscular effort.'),
('Nature','MEDIUM','Which bird is famous for mimicking chainsaws, camera shutters, and alarms?','The lyrebird','Superb lyrebirds can imitate many environmental sounds as well as other birds.'),
('Nature','EASY','What is a group of crows commonly called?','A murder','A murder is a traditional collective noun for crows.'),
('Science','MEDIUM','Which metal is liquid at ordinary room temperature?','Mercury','Mercury melts at about −39°C, so it is liquid at typical indoor temperatures.'),
('Science','EASY','Which element gives rubies their red color?','Chromium','Small amounts of chromium ions color corundum red, producing ruby.'),
('Science','MEDIUM','What is the only letter absent from the names of all 50 U.S. states?','Q','No U.S. state name contains the letter Q.'),
('Science','EASY','Which planet has the most confirmed moons in the current astronomical count?','Saturn','Saturn leads the confirmed moon count; discoveries and confirmations can change the tally.'),
('Science','MEDIUM','What is the name of the boundary where Earth''s atmosphere meets space by a common convention?','The Kármán line','The Fédération Aéronautique Internationale uses 100 kilometres as the conventional boundary.'),
('Science','EASY','Which naturally occurring substance is famously difficult to scratch?','Diamond','Diamond ranks 10 on the Mohs mineral hardness scale, though it can still fracture.'),
('Science','MEDIUM','What do you call an animal active mainly at dawn and dusk?','Crepuscular','Crepuscular animals are most active during twilight periods.'),
('Science','EASY','What gas do plants absorb from the air during photosynthesis?','Carbon dioxide','Plants use carbon dioxide and water to make sugars, releasing oxygen.'),
('Science','MEDIUM','What is the only bone in the human body not directly connected to another bone?','The hyoid','The hyoid bone is suspended in the neck by muscles and ligaments.'),
('Science','EASY','Which part of the human eye has no blood vessels and gets oxygen from tears and air?','The cornea','The transparent cornea is avascular and receives oxygen largely from the tear film and atmosphere.'),
('Food','MEDIUM','Which spice comes from the dried stigmas of a crocus flower?','Saffron','Saffron consists of the carefully harvested stigmas of Crocus sativus.'),
('Food','EASY','Which cheese traditionally has holes formed by gas from bacteria?','Emmental','Propionibacterium releases carbon dioxide during Emmental cheese ripening, forming eyes.'),
('Food','MEDIUM','What is the main flavor compound in vanilla?','Vanillin','Vanillin is the characteristic aromatic compound in vanilla beans.'),
('Food','EASY','Which nut is botanically a seed that grows outside a fruit called an apple?','Cashew','The cashew seed hangs below the cashew apple, a swollen fruit stalk.'),
('Food','MEDIUM','Which popular chocolate treat was first sold as a medicine in the 19th century?','The Hershey bar','Chocolate products have a long history as medicinal foods; this clue describes early cocoa preparations, not a single modern bar.'),
('Food','EASY','What gives chili peppers their heat?','Capsaicin','Capsaicin activates heat-sensitive receptors in the mouth.'),
('Food','MEDIUM','Which fruit floats in water because it is about one quarter air?','The apple','Air pockets in apple flesh make apples buoyant.'),
('Food','EASY','What is the primary ingredient in traditional hummus?','Chickpeas','Traditional hummus blends cooked chickpeas with tahini, lemon, and other seasonings.'),
('Food','MEDIUM','Which drink is made from roasted seeds rather than beans?','Coffee','Coffee beans are the seeds inside the fruit, or coffee cherry.'),
('Food','EASY','What type of pastry is used to make profiteroles?','Choux pastry','Profiteroles are small choux pastry puffs, often filled with cream.'),
('Geography','EASY','Which country has a national animal that is a unicorn?','Scotland','The unicorn is a heraldic national animal of Scotland.'),
('Geography','MEDIUM','What is the world''s only country that is also a continent?','Australia','Australia is both a sovereign country and the smallest continent by conventional classification.'),
('Geography','EASY','Which country has more pyramids than Egypt?','Sudan','Sudan contains more ancient pyramids, many built by the Kingdom of Kush.'),
('Geography','MEDIUM','Which capital city lies on two continents?','Istanbul','Istanbul spans the Bosporus, with districts in Europe and Asia; it is not Turkey''s capital.'),
